/**
 * Custom environment variables that are not auto-generated by wrangler.
 * Secrets are set via `wrangler secret`; vars are set in `wrangler.jsonc`.
 *
 * @author [Sergio Xalambrí](https://sergiodxa.com)
 * @copyright Sergio Xalambrí 2026
 */
declare namespace Cloudflare {
	interface Env {
		POLAR_ACCESS_TOKEN: string;
		POLAR_PRODUCT_ID: string;
		/** Verifies incoming Polar webhook signatures. */
		POLAR_WEBHOOK_SECRET?: string;
		CF_API_TOKEN: string;
		CF_ZONE_ID: string;
		CF_ACCOUNT_ID: string;
		/** Signs internal API tokens. */
		INTERNAL_SECRET: string;
		/** Signs platform session cookies. */
		SESSION_SECRET: string;

		PLATFORM_DOMAIN: string;
		EMAIL_FROM: string;

		ANALYTICS: AnalyticsEngineDataset;

		AUTH_RATE_LIMITER: RateLimit;
		STRICT_RATE_LIMITER: RateLimit;
		MANAGEMENT_RATE_LIMITER: RateLimit;
	}
}
